static void reset(){if(hx_rmt){hx_rmt->~HxrRuntime();std::free(hx_rmt);}hx_rmt=nullptr;hx_rmt_setup_tried=false;for(auto*p:fakeRmt)delete p;fakeRmt.clear();fakeNow=1000;rmtFail.clear();rmtFailUnit=-1;rmtAllocCalls=rmtReceiveCalls=rmtDeleteCalls=rmtDisableCalls=0;failRmtHeap=corruptRmtPin=false;fakeFail.clear();fakeCorruptReady=false;for(auto&p:fakePins)p={};fakePins[25].oe=true;fakePins[25].oe_ctrl_by_periph=true;fakePins[33].ie=true;fakePins[33].pu=true;hx_pcnt=HxPcntDiag();hx_pcnt.setup_code=1;hx_pcnt.stage_mask=7;hx_pcnt.gpio_function=2;hx_pcnt.gpio_signal=256;for(unsigned i=0;i<3;i++){hx_pcnt.pins[i][0]={2,256,2,i==1?29U:28U};hx_pcnt.pins[i][1]={2,256,2,5};}}
static uint32_t word(uint16_t a,bool la,uint16_t b=0,bool lb=false){return a|(la?32768U:0U)|(static_cast<uint32_t>(b)|(lb?32768U:0U))<<16;}
static void fill(){auto&w=hx_rmt->s.work[hx_rmt->s.current];for(unsigned i=0;i<25;i++)w.unit[0].symbols[i]=word(20,false,20,true);w.unit[0].symbols[25]=word(10000,false);w.unit[1].symbols[0]=word(20,false,20,true);w.unit[1].symbols[1]=word(10000,false);}
static HxDiagRecord row(uint32_t seq,bool accepted=true){HxDiagRecord r={};r.seq=seq;r.start_us=fakeNow;r.end_us=fakeNow+200;r.accepted=accepted;r.dout_after25=accepted;r.raw=-160000;r.bits24=static_cast<uint32_t>(r.raw)&0xffffff;r.pulses_issued=25;r.context_flags=3;r.flags=accepted?0:1;r.rx_before=10;r.rx_after=accepted?11:10;r.err_after=accepted?0:1;return r;}
static HxAttemptPcnt pcnt(const HxDiagRecord&r,bool diff=false){HxAttemptPcnt p;p.seq=r.seq;p.policy=159;p.prepare_begin=r.start_us-100;p.finish_end=r.end_us+100;for(unsigned i=0;i<2;i++){auto&u=p.unit[i];u.start_begin=r.start_us-90+20*i;u.start_end=u.start_begin+1;u.stop_begin=r.end_us+80-20*i;u.stop_end=u.stop_begin+1;u.read_begin=u.stop_end+1;u.read_end=u.read_begin+1;u.count=i?hxpExpectedData(r.bits24,r.dout_after25)+(diff?2:0):50;u.flags=15+112+256+512+2048+(i&&r.dout_after25?4096:0);}return p;}
static void bind(uint32_t seq=1,bool accepted=true,bool diff=false){auto r=row(seq,accepted);auto p=pcnt(r,diff);fakeNow=r.end_us;HxPcntProof proof;proof.seq=r.seq;proof.bits24=r.bits24;proof.accepted=r.accepted;proof.postcheck=r.dout_after25;
  for(uint8_t i=0;i<2;i++){auto&u=proof.unit[i];const auto&v=p.unit[i];u.start_begin=v.start_begin;u.start_end=v.start_end;u.stop_begin=v.stop_begin;u.stop_end=v.stop_end;u.read_begin=v.read_begin;u.read_end=v.read_end;u.api_mask=15;u.attempt_mask=7;u.count=v.count;u.level_start_begin=u.start_end+1;u.level_start_end=u.start_end+2;u.level_start=0;u.level_end_begin=u.stop_begin-3;u.level_end_end=u.stop_begin-2;u.level_end=i?r.dout_after25:0;}
  const auto before=hx_pcnt.proof_count;hxpAddProof(hx_pcnt,proof);p.policy=hx_pcnt.proof_count!=before?131259:159;recordHxRmt(r,p);
}
static void done(){fill();fakeNow+=1200;rmtFire(0);rmtFire(1,2);serviceHxRmt();}
